package com.sultan.jarvis.mobile;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.telecom.DisconnectCause;import android.view.*;import android.widget.*;

// This is the only screen allowed over the keyguard. It exposes call controls,
// never conversation history, files, approvals, pairing secrets or task details.
public class CallActivity extends Activity {
 static java.lang.ref.WeakReference<CallActivity> current=new java.lang.ref.WeakReference<>(null);
 final Handler handler=new Handler(Looper.getMainLooper());
 TextView status,privacy;Button answer,end,mute,audio,open;FrameLayout root;VoiceService service;boolean bound=false;
 final ServiceConnection binding=new ServiceConnection(){
  @Override public void onServiceConnected(ComponentName name,IBinder binder){service=((VoiceService.LocalBinder)binder).service();service.attachBehindCall(CallActivity.this,root);}
  @Override public void onServiceDisconnected(ComponentName n){service=null;}
 };
 boolean preview(){return BuildConfig.DEBUG&&getIntent().getBooleanExtra("preview",false);}
 final Runnable tick=new Runnable(){public void run(){if(!CallCoordinator.live()){finish();return;}render();if(!preview()&&!CallCoordinator.phase.equals("ringing")&&!bound){bound=bindService(new Intent(CallActivity.this,VoiceService.class),binding,BIND_AUTO_CREATE);}handler.postDelayed(this,500);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);if(!CallCoordinator.validAction(getIntent())){finish();return;}current=new java.lang.ref.WeakReference<>(this);if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(CallCoordinator.phase.equals("ringing"));}getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().setStatusBarColor(Color.rgb(3,12,19));getWindow().setNavigationBarColor(Color.rgb(3,12,19));build();if(getIntent().getBooleanExtra("answer",false))CallCoordinator.answer(this);handler.post(tick);}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);if(!CallCoordinator.validAction(intent))return;setIntent(intent);if(intent.getBooleanExtra("answer",false))CallCoordinator.answer(this);}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 TextView label(String text,int sp,int color){TextView view=new TextView(this);view.setText(text);view.setTextSize(sp);view.setTextColor(color);view.setGravity(Gravity.CENTER);return view;}
 Button button(String text,int color){Button b=new Button(this);b.setText(text);b.setTextSize(16);b.setTextColor(Color.WHITE);b.setAllCaps(false);GradientDrawable shape=new GradientDrawable();shape.setColor(color);shape.setCornerRadius(dp(16));b.setBackground(shape);b.setMinHeight(dp(56));return b;}
 void build(){root=new FrameLayout(this);if(Build.VERSION.SDK_INT>=30)root.setOnApplyWindowInsetsListener((view,insets)->{android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());view.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setGravity(Gravity.CENTER);panel.setPadding(dp(24),dp(24),dp(24),dp(24));panel.setBackgroundColor(0xff030c13);
  ImageView emblem=new ImageView(this);emblem.setImageResource(R.drawable.app_icon);LinearLayout.LayoutParams icon=new LinearLayout.LayoutParams(dp(140),dp(140));icon.bottomMargin=dp(24);panel.addView(emblem,icon);
  panel.addView(label("JARVIS",34,0xffe0f7ff));panel.addView(label("AI voice call",16,0xffa8cbd8));status=label("Incoming call",20,0xffc4eaf4);LinearLayout.LayoutParams statusBox=new LinearLayout.LayoutParams(-1,dp(64));statusBox.topMargin=dp(16);panel.addView(status,statusBox);
  LinearLayout controls=new LinearLayout(this);controls.setGravity(Gravity.CENTER);controls.setOrientation(LinearLayout.HORIZONTAL);mute=button("Mute",0xff183340);audio=button("Audio",0xff183340);LinearLayout.LayoutParams control=new LinearLayout.LayoutParams(0,dp(64),1);control.setMargins(dp(6),dp(8),dp(6),dp(8));controls.addView(mute,control);controls.addView(audio,new LinearLayout.LayoutParams(control));panel.addView(controls,new LinearLayout.LayoutParams(-1,-2));
  ScrollView identity=new ScrollView(this);identity.setFillViewport(true);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setGravity(Gravity.CENTER);while(panel.getChildCount()>0){android.view.View child=panel.getChildAt(0);panel.removeViewAt(0);body.addView(child);}identity.addView(body);panel.addView(identity,new LinearLayout.LayoutParams(-1,0,1));
  answer=button("Answer",0xff22785e);end=button("Decline",0xffa93b42);LinearLayout.LayoutParams action=new LinearLayout.LayoutParams(-1,dp(60));action.setMargins(dp(6),dp(8),dp(6),dp(8));panel.addView(answer,action);panel.addView(end,new LinearLayout.LayoutParams(action));
  open=button("Open JARVIS",0xff102833);panel.addView(open,new LinearLayout.LayoutParams(action));privacy=label("Unlock to view chats, tasks or approvals.",14,0xffa8cbd8);panel.addView(privacy,new LinearLayout.LayoutParams(-1,dp(56)));
  answer.setOnClickListener(v->CallCoordinator.answer(this));end.setOnClickListener(v->{boolean ringing=CallCoordinator.phase.equals("ringing");if(ringing)VoiceService.emit("callDeclined",CallCoordinator.id);CallCoordinator.end(this,ringing?DisconnectCause.REJECTED:DisconnectCause.LOCAL,"Call ended");});mute.setOnClickListener(v->CallCoordinator.setMuted(this,!CallCoordinator.userMuted));audio.setOnClickListener(v->CallCoordinator.audioRoutes(this));open.setOnClickListener(v->openApp());root.addView(panel,new FrameLayout.LayoutParams(-1,-1));setContentView(root);
 }
 void render(){if(CallCoordinator.phase.equals("active"))getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);boolean ringing=CallCoordinator.phase.equals("ringing");answer.setVisibility(ringing?View.VISIBLE:View.GONE);end.setText(ringing?"Decline":"End call");mute.setVisibility(ringing?View.GONE:View.VISIBLE);audio.setVisibility(ringing?View.GONE:View.VISIBLE);audio.setEnabled(CallCoordinator.connection!=null&&CallCoordinator.phase.equals("active"));mute.setText(CallCoordinator.muted?"Unmute":"Mute");status.setText(ringing?"Incoming call":CallCoordinator.phase.equals("active")?duration():"Connecting…");}
 String duration(){long seconds=Math.max(0,(System.currentTimeMillis()-CallCoordinator.startedAt)/1000);return String.format(java.util.Locale.ROOT,"%02d:%02d",seconds/60,seconds%60);}
 void openApp(){KeyguardManager keyguard=getSystemService(KeyguardManager.class);if(keyguard.isKeyguardLocked())keyguard.requestDismissKeyguard(this,new KeyguardManager.KeyguardDismissCallback(){@Override public void onDismissSucceeded(){startMain();}});else startMain();}
 void startMain(){startActivity(new Intent(this,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP));finish();}
 void requestMicrophone(){KeyguardManager keyguard=getSystemService(KeyguardManager.class);if(keyguard.isKeyguardLocked())keyguard.requestDismissKeyguard(this,new KeyguardManager.KeyguardDismissCallback(){@Override public void onDismissSucceeded(){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},77);}@Override public void onDismissCancelled(){VoiceService.emit("microphone",false);}});else requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},77);}
 @Override public void onRequestPermissionsResult(int code,String[] names,int[] grants){super.onRequestPermissionsResult(code,names,grants);VoiceService.emit("microphone",grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED);}
 @Override public void onBackPressed(){moveTaskToBack(true);}
 @Override protected void onDestroy(){handler.removeCallbacks(tick);if(service!=null)service.detach(this);if(bound)unbindService(binding);if(current.get()==this)current.clear();super.onDestroy();}
}
